items.mermaid:
classDiagram
  class Form { +Id +Title +Status +OwnerId +ReviewerIds }
  class FormSubmission { +Id +FormId +SubmitterId +Answers +Status +ResubmitCount +Submit() +Approve() +Reject() +Resubmit() }
  class ReviewRecord { +Id +SubmissionId +ReviewerId +Decision +Reason +ReviewedAt }
  class ReviewReminder { +SubmissionId +ReviewerId +SentAt }
  Form "1" --> "*" FormSubmission : has
  FormSubmission "1" --> "*" ReviewRecord : reviewed by
  FormSubmission "1" --> "*" ReviewReminder : reminded by

flowchart TD
  A[填寫者送出] --> B[狀態 = Pending]
  B --> C{3 工作天內處理?}
  C -->|否| D[系統每日提醒審核者] --> C
  C -->|是| E{審核者決定}
  E -->|核准| F[狀態 = Approved] --> G[寫 ReviewRecord] --> H([結束])
  E -->|退回| I{理由 ≥ 10 字?}
  I -->|否| J[拒絕操作] --> E
  I -->|是| K[狀態 = Rejected] --> L[寫 ReviewRecord] --> M[填寫者修改答案]
  M --> N[重新送出] --> B

flowchart TD
  A[載入紀錄] --> B{Status = Pending?}
  B -->|否| E1[409 INVALID_STATE]
  B -->|是| C{操作者是審核者?}
  C -->|否| E2[403]
  C -->|核准| D[Status=Approved + ReviewRecord]
  C -->|退回| F{理由 ≥ 10 字?}
  F -->|否| E3[400 REASON_TOO_SHORT]
  F -->|是| G[Status=Rejected + ReviewRecord] --> H[通知填寫者]

erDiagram
  Form ||--o{ FormSubmission : has
  FormSubmission ||--o{ ReviewRecord : reviewed
  FormSubmission ||--o{ ReviewReminder : reminded
  Form {
    uniqueidentifier Id PK
    nvarchar ReviewerIds
  }
  FormSubmission {
    uniqueidentifier Id PK
    int Status
    int ResubmitCount
  }
  ReviewRecord {
    uniqueidentifier Id PK
    uniqueidentifier SubmissionId FK
    uniqueidentifier ReviewerId
    int Decision
    nvarchar Reason
    datetime2 ReviewedAt
  }
  ReviewReminder {
    uniqueidentifier SubmissionId FK
    uniqueidentifier ReviewerId
    date Date
  }
